update_rule.pseudocode:
events = 0
if policy_active:
  for each location L:
    for each arriving person i (sample from contacts consistent with capacity):
      if i.adoption_state == 0:
        enforce = Bernoulli(policy_enforcement_probability * (base_enforcement_level * L.enforcement_level))
        if enforce:
          # choose action
          if Bernoulli(denial_prob_noncompliant):
            events += 1  # denial
          elif Bernoulli(ticket_prob_noncompliant):
            events += 1  # fine issued
record events to observable.enforcement_events_daily

for each household H:
  norm = mean(adoption_state of members)
  H.norm_strength = 0.5 * H.norm_strength + 0.5 * norm
  if Bernoulli(household_bulk_buying_propensity):
    needed = sum(max(0, 3 - inv_i) for members i)
    bulk_qty = min(household_bulk_buying_size, needed)
    if bulk_qty > 0:
      acquire from cheapest retailer with inventory >= bulk_qty (or split across)
      allocate to members with lowest inventories first

adoption_rate_daily = mean(i.adoption_state for all persons)
adoption_by_income_daily = {g: mean(adopt for persons in group g)}
if t >= 13:
  adoption_rate_last14_avg = mean(adoption_rate_daily over last 14 days)
else:
  adoption_rate_last14_avg = mean(adoption_rate_daily over days 0..t)
propagate other observables as collected
